// Payload: { employee_id, employee_name, employee_user_id, manager_user_id, hire_date, job_title }
const b = $input.first().json.body;
const add = (d) => { const x = new Date(b.hire_date); x.setDate(x.getDate() + d); return x.toISOString().slice(0, 10); };
const tasks = [
  { title: 'Ký hợp đồng và nộp hồ sơ cá nhân', assignee_role: 'hr', due_date: add(0) },
  { title: 'Tạo tài khoản email và SSO', assignee_role: 'hr', due_date: add(1) },
  { title: 'Cấp laptop và thiết bị làm việc', assignee_role: 'hr', due_date: add(3) },
  { title: 'Đăng ký BHXH, BHYT và mã số thuế', assignee_role: 'hr', due_date: add(14) },
  { title: 'Phân công mentor và giới thiệu nhóm', assignee_role: 'manager', due_date: add(3) },
  { title: 'Hoàn thành khóa nội quy và an toàn thông tin', assignee_role: 'employee', due_date: add(14) },
];
const notifications = [
  { role: 'hr', title: 'Nhân viên mới cần onboarding', message: `${b.employee_name} (${b.job_title}) bắt đầu ngày ${b.hire_date}. Checklist đã được tạo.`, ref_type: 'employee', ref_id: b.employee_id, kind: 'onboarding.started' },
];
if (b.manager_user_id) notifications.push({ user_id: b.manager_user_id, title: 'Nhân viên mới trong nhóm của bạn',
  message: `${b.employee_name} sẽ bắt đầu ngày ${b.hire_date}. Vui lòng phân công mentor.`, ref_type: 'employee', ref_id: b.employee_id, kind: 'onboarding.manager' });
if (b.employee_user_id) notifications.push({ user_id: b.employee_user_id, title: 'Chào mừng bạn đến với PeopleOS!',
  message: 'Hãy hoàn thành checklist hội nhập trong 2 tuần đầu.', ref_type: 'employee', ref_id: b.employee_id, kind: 'onboarding.welcome' });
return [{ json: { employee_id: b.employee_id, tasks, notifications } }];

// Tách danh sách thông báo thành từng item để node HTTP gọi lần lượt
const list = $('Chuan bi checklist').first().json.notifications;
return list.map(n => ({ json: n }));
